000000000000000010000000000#define MenuItem12	0b0000000000000000000100000000000#define MenuItem13	0b0000000000000000001000000000000#define MenuItem14	0b0000000000000000010000000000000#define MenuItem15	0b0000000000000000100000000000000#define MenuItem16	0b0000000000000001000000000000000#define MenuItem17	0b0000000000000010000000000000000#define MenuItem18	0b0000000000000100000000000000000#define MenuItem19	0b0000000000001000000000000000000#define MenuItem20	0b0000000000010000000000000000000#define MenuItem21	0b0000000000100000000000000000000#define MenuItem22	0b0000000001000000000000000000000#define MenuItem23	0b0000000010000000000000000000000#define MenuItem24	0b0000000100000000000000000000000#define MenuItem25	0b0000001000000000000000000000000#define MenuItem26	0b0000010000000000000000000000000#define MenuItem27	0b0000100000000000000000000000000#define MenuItem28	0b0001000000000000000000000000000#define MenuItem29	0b0010000000000000000000000000000#define MenuItem30	0b0100000000000000000000000000000#define MenuItem31	0b1000000000000000000000000000000/* *	Convenience symbol for enabling of menu items that are controlled by MacApp, *  i.e. those with I.D.s in the range 1 to 63. The value is irrelevant, since *  MacApp disables all items. */#define EnablingManagedByMacApp AllItems/* IDs for MacApp Alerts, Strings, Dialogs, Etc. */#define	phGenError					128#define	phCommandError				129#define	phUnknownErr				130#define	phSaveChanges				131#define	phRevert					132#define	phFileChanged				133#define	phPurgeOld					134#define	phReopenDoc					135#define	phSpaceIsLow				136#define	phUnsupportedConfiguration	137#define	phOfferReadOnly				138#define	phNewPublisherAlert			140#define phMultPublisherWrn			141#define phSavingMultPublisherWrn	142#define phMemFullFatalError			143#define phUnknownFatalError			144#define	phTooManyChars				150#define	phStylesTooBig				151#define	phAboutApp					201#define	stopIcon					0#define	noteIcon					1#define	cautionIcon					2#define	errReasonID					128#define	errRecoveryID				129#define	errOperationsID				130#define	errReasonIDStrings			128#define	errRecoveryIDStrings		129#define	errOperationsIDStrings		130#define errAEErrIDStrings			240/* Miscellaneous Constants */#define kForDebugging				128			// ID for mem!, seg!, res!, etc. #define kBaseMacApp					129#define		kSystemFontTextStyle	128			// TextStyle information for System Font#define		kApplFont9TextStyle		129			// TextStyle information for Application Font, 9 pt#define		kApplFont12TextStyle	130			// TextStyle information for Application Font, 12 pt#define kHierarchicalMenu 			"\0x1B"		/* Key char to indicate a menu item is hierarchical */#define	kIDBuzzString				250			/* MacApp buzz strings list */#define kViewStrings				253			// string list for strings for MacApp views#define kStandardHelpStrings		254			// string list for strings for MacApp views#define	kIDClipWindow				200			/* Id of the Clipboard window resource */#define	kIDClipView					'CLIP'		/* Standard Clipboard view type */#define kAEDispatchTable			400			/* ID of the 'aedt' resource used the AppleEvent manager */#define kAEEditionsDispatchTable	401			/* ID of the 'aedt' resource used the AppleEvent manager												for Edition events */#define kAECoreSuiteTable			402			/* ID of the 'aedt' resource used the core event suite */#define kDefaultWindowTitle			1006		// Default window title for the default window#define	kDefaultWindowID			1001		/* "Default" window 'View' resource */#define	kDefaultViewID				1002		/* "Default" view 'View' resource */#define	kIDDefaultView				'DFLT'		/* View ID of default view */#define kDefaultCredits				999			/* the great people behind this application */#define kMBarDisplayed				128			/* Default 'MBAR' id of the menus that are read in and */												/* installed in menu bar */#define kMBarNotDisplayed			129			/* Default 'MBAR' id of the menus that are read in but */												/* not installed  */#define kMBarHierarchical			130			/* Default 'MBAR' id of the menus that pop up when a */												/* menu item is choosen  */#define kMBarOpenDoc				131			/* Default 'MBAR' id of the menus that are displayed when */												/* running under OpenDoc */#define kMBarDebug					900			/* Default 'MBAR' id of the menus that are read in and */												/* installed in menu bar for the debugger */#define kOpenHandCursor				370			/* Open hand 'CURS' to indicate draggable content */#define kClosedHandCursor			371			/* Closed hand 'CURS' used while drag is in progress */#define kDirExtTypeTableID			128			/* List of extension types for MSAMs */#define mApple						1			/* MacApp does not disable any commands in this menu */#define mFile						2			/* File Menu */#define mEdit						3			/* Edit Menu */#define mDocument					20			/* Document Menu */#define mOpenDocEdit				21			/* Edit Menu with OpenDoc items */#define mEditionMgrEdit				30			/* Edit Menu with Edition Mgr support */#define mBuzzwords					128			/* Buzzwords Menu */#define mDebug						900			/* read in if debugging is turned on; number */												/* corresponds with debugging command numbers */#define mPerfMon					63			/* read in if performance monitoring is turned */												/* on. Corresponds with debugging command number. */												#define mLastMenu					63			/* MacApp disables menu titles mFile..mLastMenu */												/* generically */// The following are used in the definitions of AppleEvent resources.#define Reserved3	reserved, reserved, reserved#define Reserved8	reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved#define Reserved9	reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved#define Reserved12	reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved, reserved/*-------------------------------------Required Events-----------------------------------------*//* command numbers used to map AppleEvents to commands */#define cAppleEventReply	40				// General command number used to process											// asynchronous replies#define cFinderNew			41				// <!> The user selected the tool icon in the											// Finder and chose "Open"#define cFinderPrint	 	42				// <!> The user selected document icons in											// the Finder and chose "Print"#define cFinderOpen			43				// <!> The user selected document icons in											// the Finder and chose "Open"#define cFinderQuit		 	44				// The user chose "Shutdown" or "Restart"											// the Finder sends a 'quit' AppleEvent/*-------------------------------------AppleEvent constants------------------------------------*/#define cPalette 'cPal'	// identifier for MacApp AEOM palette class/*-------------------------------------Core Suite Events---------------------------------------*/// Command numbers for the core suite.#define	cAEClone			200#define	cAEClose			201#define	cAECountElements	202#define	cAECreateElement	203#define	cAEDelete			204#define	cAEDoObjectsExist	205#define	cAEGetClassInfo		206#define	cAEGetData			207#define	cAEGetDataSize		208#define	cAEGetEventInfo		209#define	cAEMove				210#define	cAEOpen				cFinderOpen#define	cAEPrint			cFinderPrint#define	cAEQuit				cFinderQuit#define	cAESave				214#define	cAESetData			215// Command numbers for recording.#define	cAERecordingOn		216#define	cAERecordingOff		217// Command numbers for the misc suite.#define	cAEUndo				218#define	cAERedo				219#define	cAEPaste			220#define	cAECut				221#define	cAECopy				222										// cAERevert is the same as cRevert.#define	cAERevert			34// Constant for the keyAESaveCopy parameter used in the aete resource.#define keyAESaveCopy		'svCp'		// "Save Copy" parameter for Save AppleEvent./*-------------------------------------Edition Mgr Events--------------------------------------*/// command numbers used to map Edition Manager AppleEvents to commands#define cSectionRead	 	50				// subscribers should read themselves afresh from disk#define cSectionWrite	 	51				// publishers should write themselves to an edition file#define cSectionScroll	 	52				// the user selects 'Open Publisher' for a subscriber#define cSectionCancel	 	53				// cancel this section in a document/*-------------------------------------Edition Mgr Menus--------------------------------------*/// command numbers used to for Edition Manager menu support#define cCreatePublisher	601				// the user has selected "Create Publisher…" from the Edit menu#define cSubscribeTo	 	602				// the user has selected 'Subscribe to…' from the Edit menu#define cOptions		 	603				// the user has selected a publisher in the document and											// then selected 'Publisher Options…' from the Edit menu,											// OR the user has selected a subscriber in the document and											// then selected 'Subscriber Options…' from the Edit menu#define cBorders		 	604				// the user has selected 'Show/Hide Borders' from the Edit menu#define cStopAllEditions 	605				// the user has selected 'Stop all Editions' from the Edit menu// Section Event constants#define sectionEventMsgClass	'sect'		// Section Event class#define sectionReadMsgID		'read'		// Section Read Event#define sectionWriteMsgID		'writ'		// Section Write Event#define sectionScrollMsgID		'scrl'		// Section Scroll Event#define sectionCancelMsgID		'cncl'		// Section Cancel Event/*-------------------------------------CMNU-------------------------------------*/type 'CMNU' {	integer;												// Menu ID	fill word[2];	integer 					textMenuProc = 0;			// menu def proc	fill word;	unsigned hex bitstring[31]	allEnabled = 0x7FFFFFFF;	// Enable flags	boolean 					disabled, enabled;			// Menu enable	pstring 					apple = "\0x14";			// Menu Title	wide array {		pstring;											// Item title		byte					noIcon; 					// Icon number		char					noKey = "\0x00",			// Key eqivalent								hierarchicalMenu = "\0x1B";	// hierarchical menu		char					noMark = "\0x00",			// Marking char								check = "\0x12";		fill bit;		unsigned bitstring[7]	plain;						// Style		align word;		longint 				nocommand = 0,				// Command number								/* Standard MacApp Command Numbers */								cAboutApp = 1,								cNew = 10,								cOpen = 20,								cInsert = 2004,								cSave = 30,								cClose = 31,								cSaveAs = 32,								cSaveCopy = 33,								cRevert = 34,								cShowClipboard = 35,								cQuit = 36,								cUndo = 101,								cRedo = 102,								cUndoRedo = 132,			// <!> "Undo/Redo <command>" (for single-undo)								cCut = 103,								cCopy = 104,								cPaste = 105,								cClear = 106,								cSelectAll = 110,								cTyping = 120,								cStyleChange = 130,								// Print Manager commands								cPageSetup = 176,								cCustomPageSetup = 181,	// For GX								cPrint = 178,								cPrintOne = 177,								cPrintSelection = 180,								cShowBorders = 199,																// Edition Manager commands								cCancelPublisher = 606,								cCancelSubscriber = 607,								// Drag and Drop commands								cDrag = 350,								cDrop = 351,								cDragMove = 352,								cDragMoveOut = 353,																// Performance Monitor command numbers								cPerfMonInit = 901,								cPerfMonDump = 902,								cPerfMonToggle = 903,								cPerfMonEnd = 904,																// Debug command numbers								cDebugFlags = 913,								cDoFirstClick = 915,								cRefreshFrontWindow = 917,								cModalToggle = 919,								cSetSysJust = 921,								cChangePrinterStyle = 192,								cShowBreaks = 201;	};	byte = 0;};/*-------------------------------------errs-------------------------------------*/type 'errs' {	wide array {						// Error list		integer 	whichList = 0,					minErr = -32768;	// Low error number; 0 specifies STR#		integer 	maxErr = 32767; 	// High error number		integer;						// Index in STR# of string	};};/*-------------------------------------mem!-------------------------------------*/type 'mem!' {		longint;						// add to the size of heap space.		longint;						// add to heap increment size		longint;						// add to code reserve size		longint;						// add to low space reserve size		longint;						// stack size};type 'ppc!' as 'mem!';type '68k!' as 'mem!';/*-------------------------------------TxSt-------------------------------------*/// TextStyle information is kept in a TxSt resource.  Resources of this type// are referenced by the view templates.type 'TxSt' {		unsigned byte tsPlain, tsBold, tsItalic, tsUnderline=4, tsOutline=8,					tsShadow=16, tsCondense=32, tsExtend=64;	// Font Style		align word;		integer;						// Font Size		wide array [3] {				// Font RGBColor			unsigned hex integer;		};		pstring;						// Font name};#if qCarbon#	if qDebug#			define	kGeneralRsrcName	"MacApp_car_d.rsrc"#			define	kDefaultRsrcName	"Defaults_car_d.rsrc"#			define	kDebugRsrcName		"Debug_car_d.rsrc"#			define	kDialogRsrcName		"Dialog_car_d.rsrc"#			define	kMacAppRsrcName		"MALib_car_d.rsrc"#			define	kPrintingRsrcName	"Printing_car_d.rsrc"#			define	kResourceLibRsrcName	"ResourceLib_car_d.rsrc"#		else#			define	kGeneralRsrcName	"MacApp_car_n.rsrc"#			define	kDefaultRsrcName	"Defaults_car_n.rsrc"#			define	kDebugRsrcName		"Debug_car_n.rsrc"#			define	kDialogRsrcName		"Dialog_car_n.rsrc"#			define	kMacAppRsrcName		"MALib_car_n.rsrc"#			define	kPrintingRsrcName	"Printing_car_n.rsrc"#			define	kResourceLibRsrcName	"ResourceLib_car_n.rsrc"#	endif#	define	kEditionsRsrcName	"Error: There is no Editions.rsrc for Carbon"#else#	define	kGeneralRsrcName	"MacApp.rsrc"#	define	kDefaultRsrcName	"Defaults.rsrc"#	define	kDebugRsrcName		"Debug.rsrc"#	define	kDialogRsrcName		"Dialog.rsrc"#	define	kEditionsRsrcName	"Editions.rsrc"#	define	kPrintingRsrcName	"Printing.rsrc"#	define	kResourceLibRsrcName	"ResourceLib.rsrc"#endif#endif